import { Injectable, Logger } from '@nestjs/common';
import { HealthIndicatorService } from '@nestjs/terminus';
import { PrismaService } from '../prisma/prisma.service.js';

/**
 * Pings Postgres with SELECT 1. Terminus's own PrismaHealthIndicator tries a MongoDB command first,
 * which the Postgres client generated by Prisma 7 doesn't have, so it always reports down.
 */
@Injectable()
export class DatabaseHealthIndicator {
  private readonly logger = new Logger(DatabaseHealthIndicator.name);

  constructor(
    private readonly indicator: HealthIndicatorService,
    private readonly prisma: PrismaService,
  ) {}

  isHealthy(key: string, timeoutMs = 1500) {
    return this.indicator
      .check(key)
      .attempt(async () => {
        try {
          await this.prisma.$queryRaw`SELECT 1`;
        } catch (error) {
          // The endpoint is public: log the driver's error here, answer with a plain message
          this.logger.warn(error);
          throw new Error('Database unreachable');
        }
      })
      .withTimeout(timeoutMs);
  }
}
